--- a/io/io.cpp
+++ b/io/io.cpp
@@ -772,9 +772,22 @@ extern "C" bool c_vcedbg(natl testid, natl testlen, natb* testdata)
 /// Parte C++ della primitiva vcenew()
 extern "C" bool c_vcenew()
 {
-/// @todo Scrivere il corpo della primitiva vcenew()
-// ( SOLUZIONE 2025-01-27
-//   SOLUZIONE 2025-01-27 )
+	natl pid = getpid();
+	sem_wait(ce.mutex);
+	vce_des *v = ce.vces[pid];
+	if (v) {
+		sem_signal(ce.mutex);
+		abort_p();
+	}
+	v = new vce_des;
+	if (!vce_des_init(v)) {
+		delete v;
+		sem_signal(ce.mutex);
+		return false;
+	}
+	ce.vces[pid] = v;
+	sem_signal(ce.mutex);
+	return true;
 }

 /// Parte C++ della primitiva vcewrite()
@@ -814,9 +827,66 @@ extern "C" void c_vcewrite(char c)
 /// Processo esterno associato alla periferica CE
 extern "C" void estern_ce(natq)
 {
-/// @todo Scrivere il corpo del processo esterno
-// ( SOLUZIONE 2025-01-27
-//   SOLUZIONE 2025-01-27 )
+	natl last_pid = 0;
+	for (;;) {
+		natq ev = evget();
+		if (ev == 0) {
+			sem_wait(ce.mutex);
+			if (ce.busy) {
+				ce.busy = false;
+				vce_des *v = vce_des_next(last_pid);
+				if (v) {
+					natl c = vce_des_read(v);
+					if (c != 0xFFFFFFFF) {
+						outputb(static_cast<char>(c), ce.iTBR);
+						ce.busy = true;
+					}
+					if (v->waiting) {
+						v->waiting = false;
+						sem_signal(v->sync);
+					}
+					if (v->terminated && v->n == 0) {
+						ce.vces[last_pid] = nullptr;
+						sem_signal(v->sync);
+						delete v;
+					}
+				}
+			} else {
+				vce_des *v = vce_des_next(last_pid);
+				if (v) {
+					natl c = vce_des_read(v);
+					if (c != 0xFFFFFFFF) {
+						outputb(static_cast<char>(c), ce.iTBR);
+						ce.busy = true;
+					}
+					if (v->waiting) {
+						v->waiting = false;
+						sem_signal(v->sync);
+					}
+					if (v->terminated && v->n == 0) {
+						ce.vces[last_pid] = nullptr;
+						sem_signal(v->sync);
+						delete v;
+					}
+				}
+			}
+			sem_signal(ce.mutex);
+		} else if (ev != 0xFFFFFFFF) {
+			natl term_pid = static_cast<natl>(ev);
+			sem_wait(ce.mutex);
+			vce_des *v = ce.vces[term_pid];
+			if (v) {
+				v->terminated = true;
+				if (v->n == 0) {
+					ce.vces[term_pid] = nullptr;
+					sem_signal(v->sync);
+					delete v;
+				}
+			}
+			sem_signal(ce.mutex);
+		}
+		wfi();
+	}
 }

